Method.Source:
    /// <summary>
    /// Maps entity to datasource.
    /// </summary>
    /// <param name = "_entityCtx">
    /// <c>DataEntityRuntimeContext</c>.
    /// </param>
    /// <param name = "_dataSourceCtx">
    /// <c>DataEntityDataSourceRuntimeContext</c>.
    /// </param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

        
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, METInventItemOrderSetup):
                METInventItemOrderSetup metInventItemOrderSetup   =  _dataSourceCtx.getBuffer();
                InventItemInventSetup   inventItemInventSetup  = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, InventItemInventSetup)).getBuffer();

                if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
                {                    
                    metInventItemOrderSetup.InventDimId = inventItemInventSetup.InventDimId;
                    metInventItemOrderSetup.SiteId =  InventDim::find(inventItemInventSetup.InventDimId).InventSiteId;
                }
                else if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
                {
                    if (!metInventItemOrderSetup.SiteId)
                    {
                        metInventItemOrderSetup.SiteId =  InventDim::find(inventItemInventSetup.InventDimId).InventSiteId;
                    }
                }
                break;
        }
        
    }
